-- TalentForge AI - Supabase / Postgres schema (generated by `python -m portal.dbtool schema`).

-- Safe to run more than once.

CREATE TABLE IF NOT EXISTS users (
  id BIGSERIAL PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('candidate','employer','admin')),
  consent_at TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS candidate_profiles (
  user_id BIGINT PRIMARY KEY REFERENCES users(id),
  profile_json TEXT NOT NULL,
  resume_text TEXT NOT NULL DEFAULT '',
  resume_filename TEXT NOT NULL DEFAULT '',
  target_role TEXT,
  updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS organisations (
  id BIGSERIAL PRIMARY KEY,
  owner_id BIGINT NOT NULL REFERENCES users(id),
  name TEXT NOT NULL,
  industry TEXT NOT NULL DEFAULT '',
  size TEXT NOT NULL DEFAULT '',
  website TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS jobs (
  id BIGSERIAL PRIMARY KEY,
  org_id BIGINT NOT NULL REFERENCES organisations(id),
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  location TEXT NOT NULL DEFAULT '',
  job_type TEXT NOT NULL DEFAULT 'Full-time',
  required_json TEXT NOT NULL,
  preferred_json TEXT NOT NULL DEFAULT '[]',
  min_years DOUBLE PRECISION NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('draft','open','closed')),
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS applications (
  id BIGSERIAL PRIMARY KEY,
  job_id BIGINT NOT NULL REFERENCES jobs(id),
  candidate_id BIGINT NOT NULL REFERENCES users(id),
  status TEXT NOT NULL DEFAULT 'applied',
  match_score DOUBLE PRECISION NOT NULL DEFAULT 0,
  match_json TEXT NOT NULL DEFAULT '{}',
  applied_at TEXT NOT NULL,
  UNIQUE(job_id, candidate_id)
);
CREATE TABLE IF NOT EXISTS decisions (
  id BIGSERIAL PRIMARY KEY,
  application_id BIGINT NOT NULL REFERENCES applications(id),
  decision TEXT NOT NULL,
  reason TEXT NOT NULL,
  ai_recommendation TEXT NOT NULL,
  feedback TEXT NOT NULL DEFAULT '',
  share_feedback BIGINT NOT NULL DEFAULT 0,
  decided_by BIGINT NOT NULL REFERENCES users(id),
  decided_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS ai_results (
  id BIGSERIAL PRIMARY KEY,
  type TEXT NOT NULL,
  subject TEXT NOT NULL,
  output_json TEXT NOT NULL,
  model TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS audit_events (
  id BIGSERIAL PRIMARY KEY,
  actor_id BIGINT,
  action TEXT NOT NULL,
  ref TEXT NOT NULL DEFAULT '',
  detail TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS narrative_cache (
  key TEXT PRIMARY KEY,
  text TEXT NOT NULL,
  source TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS resumes (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  title TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT 'builder',
  is_default BIGINT NOT NULL DEFAULT 0,
  parent_id BIGINT,
  job_title TEXT NOT NULL DEFAULT '',
  job_company TEXT NOT NULL DEFAULT '',
  template TEXT NOT NULL DEFAULT 'classic',
  data_json TEXT NOT NULL,
  score DOUBLE PRECISION NOT NULL DEFAULT 0,
  score_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS job_agents (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  name TEXT NOT NULL,
  query TEXT NOT NULL,
  locations_json TEXT NOT NULL DEFAULT '[]',
  work_modes_json TEXT NOT NULL DEFAULT '["remote","onsite","hybrid"]',
  level TEXT NOT NULL DEFAULT 'entry',
  sources_json TEXT NOT NULL DEFAULT '[]',
  resume_id BIGINT,
  min_score DOUBLE PRECISION NOT NULL DEFAULT 0,
  active BIGINT NOT NULL DEFAULT 1,
  last_run_at TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS agent_runs (
  id BIGSERIAL PRIMARY KEY,
  agent_id BIGINT NOT NULL REFERENCES job_agents(id),
  started_at TEXT NOT NULL,
  finished_at TEXT,
  found BIGINT NOT NULL DEFAULT 0,
  new_count BIGINT NOT NULL DEFAULT 0,
  log_json TEXT NOT NULL DEFAULT '[]'
);
CREATE TABLE IF NOT EXISTS job_results (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  agent_id BIGINT,
  source TEXT NOT NULL,
  external_id TEXT NOT NULL,
  title TEXT NOT NULL,
  company TEXT NOT NULL DEFAULT '',
  location TEXT NOT NULL DEFAULT '',
  remote BIGINT,
  url TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  posted_at TEXT NOT NULL DEFAULT '',
  salary TEXT NOT NULL DEFAULT '',
  via TEXT NOT NULL DEFAULT '',
  tags_json TEXT NOT NULL DEFAULT '[]',
  match_score DOUBLE PRECISION NOT NULL DEFAULT 0,
  match_json TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'new',
  found_at TEXT NOT NULL,
  UNIQUE(user_id, source, external_id)
);

ALTER TABLE users ADD COLUMN IF NOT EXISTS auth_uid TEXT;

CREATE UNIQUE INDEX IF NOT EXISTS users_auth_uid_idx ON users(auth_uid);

ALTER TABLE resumes ADD COLUMN IF NOT EXISTS accent TEXT NOT NULL DEFAULT '';

ALTER TABLE resumes ADD COLUMN IF NOT EXISTS raw_text TEXT NOT NULL DEFAULT '';

ALTER TABLE resumes ADD COLUMN IF NOT EXISTS parse_json TEXT NOT NULL DEFAULT '{}';

-- The browser-facing (anon) key must not be able to read anything through Supabase's REST API.
-- With RLS enabled and no policies, only this server's database role can access the tables.

ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE candidate_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE organisations ENABLE ROW LEVEL SECURITY;
ALTER TABLE jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE applications ENABLE ROW LEVEL SECURITY;
ALTER TABLE decisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_results ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE narrative_cache ENABLE ROW LEVEL SECURITY;
ALTER TABLE resumes ENABLE ROW LEVEL SECURITY;
ALTER TABLE job_agents ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE job_results ENABLE ROW LEVEL SECURITY;
